// PWA كاملة: manifest + أيقونات + service worker + صفحة بلا اتصال (كلها في ملف واحد)
const ICON192 = Buffer.from('', 'base64');
const ICON512 = Buffer.from('', 'base64');
const ICONMASK = Buffer.from('', 'base64');

const MANIFEST = {
  name: 'LHT+ — تمارين، تغذية، وأبطال',
  short_name: 'LHT+',
  description: 'منصتك الكاملة للتمارين والتغذية والتدريب الخاص',
  lang: 'ar', dir: 'rtl', id: '/', start_url: '/', scope: '/',
  display: 'standalone', orientation: 'portrait',
  background_color: '#050b1a', theme_color: '#050b1a',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/icon-maskable.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
};

const SW = "const V='lht-v2',SHELL=['/','/offline'];" +
  "self.addEventListener('install',e=>{e.waitUntil(caches.open(V).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting()));});" +
  "self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(x=>x!==V).map(x=>caches.delete(x)))).then(()=>clients.claim()));});" +
  "self.addEventListener('fetch',e=>{const r=e.request;if(r.method!=='GET')return;const u=new URL(r.url);if(u.origin!==location.origin||u.pathname.startsWith('/api/'))return;" +
  "if(r.mode==='navigate'){e.respondWith(fetch(r).then(x=>{const c=x.clone();caches.open(V).then(k=>k.put('/',c));return x;}).catch(()=>caches.match('/').then(m=>m||caches.match('/offline'))));return;}" +
  "e.respondWith(caches.match(r).then(m=>{const f=fetch(r).then(x=>{caches.open(V).then(k=>k.put(r,x.clone()));return x;}).catch(()=>m);return m||f;}));});";

const OFFLINE = '<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LHT+</title>' +
  '<body style="margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#050b1a;color:#fff;font-family:sans-serif;text-align:center">' +
  '<div><div style="font-size:48px">📡</div><h2>لا يوجد اتصال بالإنترنت</h2><p style="opacity:.7">تحقق من الشبكة ثم أعد المحاولة.</p>' +
  '<button onclick="location.reload()" style="padding:10px 22px;border-radius:99px;border:1px solid #ffd700;background:none;color:#ffd700;font-size:16px">إعادة المحاولة</button></div></body></html>';

module.exports = function (app) {
  app.get('/manifest.json', (req, res) => res.type('application/manifest+json').send(JSON.stringify(MANIFEST)));
  app.get('/icon-192.png', (req, res) => res.type('image/png').set('Cache-Control', 'public, max-age=604800').send(ICON192));
  app.get('/icon-512.png', (req, res) => res.type('image/png').set('Cache-Control', 'public, max-age=604800').send(ICON512));
  app.get('/icon-maskable.png', (req, res) => res.type('image/png').set('Cache-Control', 'public, max-age=604800').send(ICONMASK));
  app.get('/sw.js', (req, res) => res.type('application/javascript').set('Cache-Control', 'no-cache').send(SW));
  app.get('/offline', (req, res) => res.type('html').send(OFFLINE));
};
